# Samatwam Studio teasers T2 (glass desk) and T3 (ring to light), rendered with Cycles on the Kaggle GPU.
# Stops at once if no GPU is found. Progress is written to progress.txt; videos are encoded here so the download stays small.
import os, subprocess, base64, time, shutil, json, glob
W = '/kaggle/working'; T = '/kaggle/tmp'; os.makedirs(T + '/tex', exist_ok=True); os.chdir(T)
t0 = time.time(); LOG = open(os.path.join(W, 'progress.txt'), 'a')
def log(m): line = f"[{time.time()-t0:7.1f}s] {m}"; print(line, flush=True); LOG.write(line + chr(10)); LOG.flush()
g = subprocess.run('nvidia-smi --query-gpu=name,memory.total --format=csv,noheader', shell=True, capture_output=True, text=True).stdout.strip()
log('GPU: ' + (g or 'NONE'))
if not g: log('NO GPU, stopping'); raise SystemExit(0)
FILES = json.loads('{"ring_film.py": "", "logo_tile.png": "", "glass_desk.py": "", "tex/field.jpg": "", "tex/build.webp": "", "tex/commons.webp": ""}')
for k, v in FILES.items(): open(k, 'wb').write(base64.b64decode(v))
subprocess.run('wget -q https://download.blender.org/release/Blender4.5/blender-4.5.16-linux-x64.tar.xz && tar xf blender-4.5.16-linux-x64.tar.xz && mv blender-4.5.16-linux-x64 blender', shell=True, check=True)
subprocess.run('apt-get install -y -q libxi6 libxkbcommon0 libsm6 libxrender1 libxfixes3 libgl1 >/dev/null 2>&1', shell=True)
log('blender ready; ffmpeg: ' + (shutil.which('ffmpeg') or 'missing'))
if not shutil.which('ffmpeg'): subprocess.run('pip -q install imageio-ffmpeg', shell=True)
def ff():
    if shutil.which('ffmpeg'): return 'ffmpeg'
    import imageio_ffmpeg; return imageio_ffmpeg.get_ffmpeg_exe()
def run(cmd, name, limit):
    s = time.time()
    try: r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=limit)
    except subprocess.TimeoutExpired: log(f'{name} TIMED OUT after {limit}s'); return False
    dev = [l for l in r.stdout.splitlines() if 'CYCLES_DEVICE' in l]
    log(f'{name} done in {time.time()-s:.0f}s rc={r.returncode} {dev[:1]}')
    if r.returncode: log(r.stdout[-1500:] + r.stderr[-1500:])
    return r.returncode == 0
os.makedirs(W + '/stills', exist_ok=True)
# GPU check: one frame each, also timed so the full runs can be estimated
if not run(f'./blender/blender -b -P glass_desk.py -- --gpu --frame 200 --anim 360 --samples 128 --res 1920x1080 --out {W}/stills/T2_check.png', 'T2 check frame', 900): raise SystemExit(0)
run(f'./blender/blender -b -P ring_film.py -- --gpu --shot black_push --anim 240 --frame 200 --samples 128 --res 1920x1080 --out {W}/stills/T3_check.png', 'T3 check frame', 900)
def anim(cmd, name, frames, mp4):
    os.makedirs(T + '/' + name, exist_ok=True)
    ok = run(cmd + f' --out {T}/{name}/####', name + f' {frames} frames', 4 * 3600)
    n = len(glob.glob(f'{T}/{name}/*.png')); log(f'{name}: {n} frames on disk')
    if n: subprocess.run(f'{ff()} -y -loglevel error -framerate 60 -i {T}/{name}/%04d.png -c:v libx264 -preset slow -crf 12 -pix_fmt yuv420p {W}/{mp4}', shell=True); log(mp4 + ' encoded')
    for i in (1, frames // 2, frames):
        p = f'{T}/{name}/{i:04d}.png'
        if os.path.exists(p): shutil.copy(p, f'{W}/stills/{name}_{i:04d}.png')
anim('./blender/blender -b -P glass_desk.py -- --gpu --anim 360 --samples 128 --res 1920x1080', 'T2', 360, 'T2_GlassDesk.mp4')
anim('./blender/blender -b -P ring_film.py -- --gpu --shot black_push --anim 240 --samples 128 --res 1920x1080', 'T3', 240, 'T3_RingPush.mp4')
log('all done')
